def get_instruction_and_query(
    query_text,
    default_instruction=None,
):
    if default_instruction is None:
        default_instruction = (
            "Given a web search query, retrieve relevant passages that answer the query"
        )
    # detect if any of the prompts in ALL_TASK_PROMPTS is in query_text
    for prompt in ALL_TASK_PROMPTS:
        if prompt in query_text:
            task_description = prompt.replace(":", ".").strip()
            if task_description.endswith("."):
                task_description = task_description[:-1]
            return task_description, query_text.replace(prompt, "").strip()
    return (
        default_instruction,
        query_text,
    )
